INSERT INTO communication_categories(id,name,description,auto_generated_text,system_defined) SELECT '10000000-0000-0000-0000-000000000001', 'Welcome', 'Welcome messages', FALSE, TRUE WHERE NOT EXISTS (SELECT 1 FROM communication_categories WHERE name='Welcome');
INSERT INTO communication_categories(id,name,description,auto_generated_text,system_defined) SELECT '10000000-0000-0000-0000-000000000002', 'Goodbye', 'Goodbye messages', FALSE, TRUE WHERE NOT EXISTS (SELECT 1 FROM communication_categories WHERE name='Goodbye');
INSERT INTO communication_categories(id,name,description,auto_generated_text,system_defined) SELECT '10000000-0000-0000-0000-000000000008', 'General', 'General messages', FALSE, TRUE WHERE NOT EXISTS (SELECT 1 FROM communication_categories WHERE name='General');
UPDATE communication_categories SET auto_generated_text=FALSE, system_defined=TRUE WHERE name IN ('Welcome','Goodbye','General');
UPDATE communication_policies SET category_id=(SELECT id FROM communication_categories WHERE name='Welcome'), version=version+1 WHERE communication_event_type='ENTER_REGION' AND category_id<>(SELECT id FROM communication_categories WHERE name='Welcome');
UPDATE communication_policies SET category_id=(SELECT id FROM communication_categories WHERE name='Goodbye'), version=version+1 WHERE communication_event_type='EXIT_REGION' AND category_id<>(SELECT id FROM communication_categories WHERE name='Goodbye');
UPDATE communication_policies SET category_id=(SELECT id FROM communication_categories WHERE name='General'), version=version+1 WHERE communication_event_type IN ('SCHEDULED_ONCE','SCHEDULED_RECURRING','SHRIEK_HEARD') AND category_id<>(SELECT id FROM communication_categories WHERE name='General');
